-- Synthetic payload only. Existing RPCs must preserve new activity fields and
-- append-only observations. This runs in the isolated local harness, never hosted.
begin;
create function pg_temp.activity_ok(v boolean,label text) returns void language plpgsql as $$
begin if v is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end $$;
create function pg_temp.activity_payload() returns jsonb language sql as $$ select
 '{"active":{"meal":{"version":1,"id":"10000000-0000-4000-8000-000000000003","name":"Synthetic parallel activities","serveAt":"2026-11-22T20:00:00Z","mode":"cooking","startedAt":"2026-11-22T12:00:00Z","dishes":[{"id":"wings","name":"Wings","preset":"custom","equipment":"Smoker + fryer","cookMinutes":0,"restMinutes":0,"activities":{"version":1,"definitions":[{"id":"smoke","stage":"cooking","startStepId":"start","endStepId":"remove","checkpointStepIds":["check"],"provenance":"confirmed"}]}}],"completed":{"wings:start":"2026-11-22T12:00:00Z","wings:check":"2026-11-22T13:00:00Z"},"notes":{},"phasePlan":{"version":1,"activityVersion":1,"phases":[{"id":"wings:smoke","dishId":"wings","stage":"cooking","kind":"heating","independent":true,"startTaskId":"wings:start","endTaskIds":["wings:remove"],"durationTaskId":"wings:start","minutes":null}],"actions":{"wings:start":{"starts":["wings:smoke"]},"wings:remove":{"ends":["wings:smoke"]},"wings:check":{"observes":["wings:smoke"]}},"order":{"wings":["wings:start","wings:check","wings:remove"]},"suppressed":[]},"events":[{"id":"parallel-start","taskId":"wings:start","kind":"completed","occurredAt":"2026-11-22T12:00:00Z","phaseObservations":[{"phaseId":"wings:smoke","boundary":"start"}]},{"id":"parallel-reading-1","taskId":"wings:check","kind":"temperature","occurredAt":"2026-11-22T13:00:00Z","value":145,"unit":"°F","activityId":"wings:smoke"},{"id":"parallel-reading-2","taskId":"wings:check","kind":"temperature","occurredAt":"2026-11-22T13:10:00Z","value":162,"unit":"°F","activityId":"wings:smoke"},{"id":"parallel-note","taskId":"wings:check","kind":"equipment","occurredAt":"2026-11-22T13:11:00Z","note":"Synthetic observation","observationType":"note","activityId":"wings:smoke"}]},"serveInstant":"2026-11-22T20:00:00Z"},"history":[]}'::jsonb $$;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select public.save_cook_workspace(auth.uid(),0,'30000000-0000-4000-8000-000000000003',pg_temp.activity_payload(),'America/New_York');
select pg_temp.activity_ok(public.load_cook_workspace(auth.uid())->'active'->'meal'=pg_temp.activity_payload()->'active'->'meal','activity definitions, start and repeated observations round-trip through existing workspace RPC');
select pg_temp.activity_ok((select count(*)=4 from public.cook_events),'every physical/reading/note event retained independently');
select pg_temp.activity_ok((select payload->>'activityId'='wings:smoke' and occurred_at='2026-11-22T13:10:00Z'::timestamptz from public.cook_events where payload->>'id'='parallel-reading-2'),'activity attribution and exact observation time retained');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select pg_temp.activity_ok(public.load_cook_workspace(auth.uid())->'active'='null'::jsonb,'another owner cannot read the parallel cook');
rollback;
